package com.cognitivekernel.androidfit;
import android.app.*;import android.os.Bundle;import android.view.View;import android.widget.*;import android.content.*;import android.content.res.Configuration;import android.database.Cursor;import android.hardware.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import androidx.core.graphics.Insets;import androidx.core.view.ViewCompat;import androidx.core.view.WindowCompat;import androidx.core.view.WindowInsetsCompat;
public class MainActivity extends Activity implements SensorEventListener {
 static final String PREFS="fityar_preferences", LANGUAGE="language";
 @Override protected void attachBaseContext(Context newBase){super.attachBaseContext(localizedContext(newBase));}
 static Context localizedContext(Context context){String language=context.getSharedPreferences(PREFS,Context.MODE_PRIVATE).getString(LANGUAGE,"fa");Locale locale=Locale.forLanguageTag(language);Locale.setDefault(locale);Configuration config=new Configuration(context.getResources().getConfiguration());config.setLocale(locale);return context.createConfigurationContext(config);}
 void chooseLanguage(){String[] labels={"فارسی","English"};new AlertDialog.Builder(this).setTitle(getString(R.string.choose_language_title)).setItems(labels,(dialog,which)->{String selected=which==0?"fa":"en";getSharedPreferences(PREFS,MODE_PRIVATE).edit().putString(LANGUAGE,selected).apply();recreate();}).setCancelable(false).show();}

 WorkoutDb db; AdvancedFeatures advanced; TextView status; SensorManager sm; Sensor step; float base=-1; static final int EXPORT=10;
 public void onCreate(Bundle b){super.onCreate(b);WindowCompat.setDecorFitsSystemWindows(getWindow(),false);setContentView(R.layout.activity_main);View root=findViewById(R.id.rootContainer);ViewCompat.setOnApplyWindowInsetsListener(root,(v,insets)->{Insets bars=insets.getInsets(WindowInsetsCompat.Type.systemBars());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);return insets;});db=new WorkoutDb(this);advanced=new AdvancedFeatures(this,db);status=findViewById(R.id.statusText);findViewById(R.id.managePlansButton).setOnClickListener(v->manage());findViewById(R.id.logWorkoutButton).setOnClickListener(v->log());findViewById(R.id.stepsButton).setOnClickListener(v->steps());findViewById(R.id.exportButton).setOnClickListener(v->export());findViewById(R.id.languageButton).setOnClickListener(v->chooseLanguage());findViewById(R.id.personalPlanButton).setOnClickListener(v->advanced.buildPersonalPlan());findViewById(R.id.historyButton).setOnClickListener(v->advanced.showHistory());findViewById(R.id.libraryButton).setOnClickListener(v->advanced.showLibrary());findViewById(R.id.coachButton).setOnClickListener(v->advanced.showCoach());findViewById(R.id.backupButton).setOnClickListener(v->advanced.backup());findViewById(R.id.restoreButton).setOnClickListener(v->advanced.restore());findViewById(R.id.reminderButton).setOnClickListener(v->advanced.showReminders());findViewById(R.id.weeklyGoalButton).setOnClickListener(v->advanced.showWeeklyGoal());sm=(SensorManager)getSystemService(SENSOR_SERVICE);step=sm.getDefaultSensor(Sensor.TYPE_STEP_COUNTER);if(!getSharedPreferences(PREFS,MODE_PRIVATE).contains(LANGUAGE))chooseLanguage();}
 EditText edit(String h,String val){EditText e=new EditText(this);e.setHint(h);if(val!=null)e.setText(val);e.setSingleLine(true);return e;} void msg(String t,String m){new AlertDialog.Builder(this).setTitle(t).setMessage(m).setPositiveButton(getString(R.string.ok),null).show();}
 void manage(){List<String[]> p=db.plans();String[] a=new String[p.size()+1];a[0]=getString(R.string.new_plan);for(int i=0;i<p.size();i++)a[i+1]=p.get(i)[1];new AlertDialog.Builder(this).setTitle(getString(R.string.plans_title)).setItems(a,(d,w)->{if(w==0){EditText n=edit(getString(R.string.plan_name_hint),null);new AlertDialog.Builder(this).setView(n).setPositiveButton(getString(R.string.save),(x,y)->{String s=n.getText().toString().trim();if(!s.isEmpty())showPlan(new String[]{""+db.addPlan(s),s});}).setNegativeButton(getString(R.string.cancel),null).show();}else showPlan(p.get(w-1));}).setNegativeButton(getString(R.string.close),null).show();}
 void showPlan(String[] p){List<String[]> e=db.exercises(Long.parseLong(p[0]));String[] a=new String[e.size()+2];a[0]=getString(R.string.add_exercise);a[1]=getString(R.string.delete_plan);for(int i=0;i<e.size();i++)a[i+2]=getString(R.string.plan_exercise_item,e.get(i)[1],e.get(i)[2],e.get(i)[3]);new AlertDialog.Builder(this).setTitle(p[1]).setItems(a,(d,w)->{if(w==0)addEx(p);else if(w==1){new AlertDialog.Builder(this).setMessage(getString(R.string.delete_plan_confirmation)).setPositiveButton(getString(R.string.delete),(x,y)->{db.deletePlan(Long.parseLong(p[0]));manage();}).setNegativeButton(getString(R.string.cancel),null).show();}else editEx(e.get(w-2));}).setPositiveButton(getString(R.string.done),null).show();}
 void addEx(String[] p){LinearLayout l=new LinearLayout(this);l.setOrientation(1);EditText n=edit(getString(R.string.exercise_name_hint),null),s=edit(getString(R.string.sets_hint),"3"),r=edit(getString(R.string.reps_hint),"10");s.setInputType(2);r.setInputType(2);l.addView(n);l.addView(s);l.addView(r);new AlertDialog.Builder(this).setTitle(getString(R.string.add_exercise_title)).setView(l).setPositiveButton(getString(R.string.save),(d,w)->{try{if(n.getText().toString().trim().isEmpty()||Integer.parseInt(s.getText().toString())<1||Integer.parseInt(r.getText().toString())<1)throw new Exception();db.addExercise(Long.parseLong(p[0]),n.getText().toString().trim(),Integer.parseInt(s.getText().toString()),Integer.parseInt(r.getText().toString()));showPlan(p);}catch(Exception e){msg(getString(R.string.error),getString(R.string.enter_valid_values));}}).setNegativeButton(getString(R.string.cancel),null).show();}
 void editEx(String[] e){LinearLayout l=new LinearLayout(this);l.setOrientation(1);EditText n=edit(getString(R.string.exercise_name_hint),e[1]),s=edit(getString(R.string.sets_hint),e[2]),r=edit(getString(R.string.reps_hint),e[3]);s.setInputType(2);r.setInputType(2);l.addView(n);l.addView(s);l.addView(r);new AlertDialog.Builder(this).setTitle(getString(R.string.edit_exercise)).setView(l).setPositiveButton(getString(R.string.save),(d,w)->{try{String name=n.getText().toString().trim();int sets=Integer.parseInt(s.getText().toString()),reps=Integer.parseInt(r.getText().toString());if(name.isEmpty()||sets<1||reps<1)throw new Exception();db.updateExercise(Long.parseLong(e[0]),name,sets,reps);msg(getString(R.string.save),getString(R.string.done_message));}catch(Exception x){msg(getString(R.string.error),getString(R.string.invalid_values));}}).setNeutralButton(getString(R.string.delete),(d,w)->db.deleteExercise(Long.parseLong(e[0]))).setNegativeButton(getString(R.string.cancel),null).show();}
 void log(){List<String[]> p=db.plans();if(p.isEmpty()){msg(getString(R.string.no_plans_title),getString(R.string.create_plan_first));return;}String[] pn=new String[p.size()];for(int i=0;i<p.size();i++)pn[i]=p.get(i)[1];LinearLayout l=new LinearLayout(this);l.setOrientation(1);Calendar c=Calendar.getInstance();final String[] date={JalaliDate.fromGregorian(c.get(Calendar.YEAR),c.get(Calendar.MONTH)+1,c.get(Calendar.DAY_OF_MONTH))};TextView dt=new TextView(this);dt.setText(getString(R.string.jalali_date_format,date[0]));l.addView(dt);dt.setOnClickListener(v->{Calendar q=Calendar.getInstance();new DatePickerDialog(this,(z,y,m,day)->{date[0]=JalaliDate.fromGregorian(y,m+1,day);dt.setText(getString(R.string.jalali_date_format,date[0]));},q.get(Calendar.YEAR),q.get(Calendar.MONTH),q.get(Calendar.DAY_OF_MONTH)).show();});Spinner ps=new Spinner(this);ps.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,pn));l.addView(ps);Spinner es=new Spinner(this);l.addView(es);TextView spec=new TextView(this);l.addView(spec);EditText kg=edit(getString(R.string.weight_hint),"0");kg.setInputType(8194);l.addView(kg);EditText rest=edit(getString(R.string.rest_seconds_hint),"60");rest.setInputType(2);l.addView(rest);EditText effort=edit(getString(R.string.effort_hint),"7");effort.setInputType(2);l.addView(effort);EditText notes=edit(getString(R.string.notes_hint),null);l.addView(notes);Runnable load=()->{int i=ps.getSelectedItemPosition();if(i<0)return;List<String[]> ex=db.exercises(Long.parseLong(p.get(i)[0]));String[] ns=new String[ex.size()];for(int j=0;j<ex.size();j++)ns[j]=ex.get(j)[1];es.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,ns));if(!ex.isEmpty())spec.setText(getString(R.string.exercise_spec,ex.get(0)[2],ex.get(0)[3]));};ps.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){}public void onItemSelected(AdapterView<?> a,View v,int i,long id){load.run();}});es.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){}public void onItemSelected(AdapterView<?> a,View v,int i,long id){int j=ps.getSelectedItemPosition();if(j>=0){List<String[]> ex=db.exercises(Long.parseLong(p.get(j)[0]));if(i>=0&&i<ex.size())spec.setText(getString(R.string.exercise_spec,ex.get(i)[2],ex.get(i)[3]));}}});new AlertDialog.Builder(this).setTitle(getString(R.string.log_workout_title)).setView(l).setPositiveButton(getString(R.string.log),(d,w)->{try{int i=ps.getSelectedItemPosition(),j=es.getSelectedItemPosition();List<String[]> ex=db.exercises(Long.parseLong(p.get(i)[0]));if(j<0||j>=ex.size())throw new Exception();String[] e=ex.get(j);db.logDetailed(date[0],p.get(i)[1],e[1],Integer.parseInt(e[2]),Integer.parseInt(e[3]),Double.parseDouble(kg.getText().toString()),Integer.parseInt(rest.getText().toString()),Integer.parseInt(effort.getText().toString()),notes.getText().toString());status.setText(getString(R.string.last_logged_format,date[0]));msg(getString(R.string.logged_title),getString(R.string.workout_saved));}catch(Exception x){msg(getString(R.string.error),getString(R.string.enter_valid_exercise_weight));}}).setNegativeButton(getString(R.string.cancel),null).show();}
 void steps(){if(step==null){msg(getString(R.string.unavailable),getString(R.string.step_sensor_unavailable));return;}if(android.os.Build.VERSION.SDK_INT>=29&&checkSelfPermission("android.permission.ACTIVITY_RECOGNITION")!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{"android.permission.ACTIVITY_RECOGNITION"},21);return;}startSteps();}void startSteps(){base=-1;sm.registerListener(this,step,SensorManager.SENSOR_DELAY_NORMAL);msg(getString(R.string.step_counter_title),getString(R.string.walk_a_few_steps));}public void onRequestPermissionsResult(int requestCode,String[] permissions,int[] grantResults){super.onRequestPermissionsResult(requestCode,permissions,grantResults);if(advanced!=null)advanced.onRequestPermissionsResult(requestCode,grantResults);if(requestCode==21&&grantResults.length>0&&grantResults[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)startSteps();else if(requestCode==21)msg(getString(R.string.permission_required),getString(R.string.activity_permission_message));}public void onSensorChanged(SensorEvent e){if(base<0)base=e.values[0];status.setText(getString(R.string.step_count_format,Math.max(0,(int)(e.values[0]-base))));}public void onAccuracyChanged(Sensor s,int a){}protected void onPause(){super.onPause();if(sm!=null)sm.unregisterListener(this);}
 void export(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("text/csv");i.putExtra(Intent.EXTRA_TITLE,getString(R.string.csv_filename));startActivityForResult(i,EXPORT);}protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(advanced!=null&&advanced.onActivityResult(r,c,d))return;if(r==EXPORT&&c==RESULT_OK&&d!=null)try(OutputStream o=getContentResolver().openOutputStream(d.getData());Cursor cur=db.allLogs()){if(o==null)throw new IOException(getString(R.string.export_destination_error));o.write(getString(R.string.csv_header).getBytes(StandardCharsets.UTF_8));while(cur.moveToNext()){StringBuilder b=new StringBuilder();for(int j=0;j<9;j++){if(j>0)b.append(',');String cell=cur.getString(j);if(cell==null)cell="";b.append('"').append(cell.replace("\"","\"\"")).append('"');}o.write((b+"\n").getBytes(StandardCharsets.UTF_8));}msg(getString(R.string.done_message),getString(R.string.file_saved));}catch(Exception e){msg(getString(R.string.error),getString(R.string.export_failed));}}
}
